H,W=27,23
out=[[8]*W for _ in range(H)]
frames=[(1,5,1,11,2),(7,11,1,11,4),(13,17,1,11,3),(19,23,1,11,1)]
for r1,r2,c1,c2,col in frames:
    for r in range(r1,r2+1):
        for c in range(c1,c2+1):
            if r in (r1,r2) or c in (c1,c2): out[r][c]=col
counts={2:2,4:4,3:1,1:1}
for r1,r2,c1,c2,col in frames:
    mid=(r1+r2)//2
    slots=[3,5,7,9]
    for c in slots[-counts[col]:]: out[mid][c]=col
print('\n'.join(' '.join(map(str,row)) for row in out))
